//! Every package that ships is named in the licence notices, and the notices carry real terms.
//!
//! # Why this is a test and not a build step
//!
//! `THIRD-PARTY-NOTICES.txt` is generated by `scripts/collect-licences.py` and checked in, which
//! means it can go stale the moment a dependency is added. A stale notices file is worse than an
//! obviously missing one: it looks like the obligation is met, and the package that was added
//! after it was last generated is the one whose licence is not being carried.
//!
//! Generating it during the build instead would need the crate registry unpacked and Python on the
//! path at build time, on every machine that builds the app. Checking it and testing it puts the
//! cost on whoever changes the dependencies, which is where it belongs.
//!
//! # What it does not check
//!
//! Not that the licence texts are *correct* — nothing here can read a licence and judge it. What
//! it checks is that nothing shipped is unaccounted for, and that the file has not been emptied or
//! replaced by a summary at some point. Those are the failures that would happen silently.

use std::path::{Path, PathBuf};

fn root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("core/ has a parent")
        .to_path_buf()
}

fn notices() -> String {
    let path = root().join("src-tauri").join("THIRD-PARTY-NOTICES.txt");
    std::fs::read_to_string(&path).unwrap_or_else(|error| {
        panic!(
            "{} could not be read ({error}).\n\
             Generate it with: python scripts/collect-licences.py",
            path.display()
        )
    })
}

/// The crates the shipped binary actually links, from the **resolved** dependency graph.
///
/// # Why this asks cargo rather than reading the manifests
///
/// It used to be a text scan of `core/Cargo.toml` and `src-tauri/Cargo.toml`. That could see which
/// crates are named, and could not see which are *selected* — so when `ts-rs` arrived behind the
/// off-by-default `typescript` feature it demanded a notice for a crate the app does not contain.
/// The first fix skipped every line marked `optional = true`, and that was too broad in the other
/// direction: **an optional dependency ships as soon as any enabled feature turns it on**, whether
/// that is a default feature or one selected further up the tree. A scan cannot tell those apart.
///
/// So this asks the resolver the same question `scripts/collect-licences.py` asks, in the same way:
/// the normal edges of `sakatsu-desktop`, which is the release target. What is compared is then the
/// set the generator wrote against the set that is linked — no inference in between.
///
/// Transitive crates are included, which the scan could never enumerate, so this is a wider check
/// as well as a correct one.
fn resolved_graph(package: &str, features: &[&str]) -> Vec<String> {
    let mut command = std::process::Command::new(env!("CARGO"));
    command
        .args(["tree", "-p", package, "--edges", "normal"])
        // The notices accompany the Windows release, not a desktop build for the test host.
        // Share the generator's target so a Linux CI run checks the same shipped graph.
        .args([
            "--locked",
            "--target",
            include_str!("../../scripts/notices-target.txt").trim(),
        ])
        .args(["--prefix", "none", "--format", "{p}"])
        // Offline because the lockfile is complete and a test must not reach the network. A
        // missing lock entry fails loudly here rather than silently resolving something new.
        .arg("--offline")
        .current_dir(root());
    for feature in features {
        command.args(["--features", feature]);
    }
    let output = command
        .output()
        .unwrap_or_else(|error| panic!("could not run `cargo tree`: {error}"));
    assert!(
        output.status.success(),
        "`cargo tree -p {package}` failed:\n{}",
        String::from_utf8_lossy(&output.stderr)
    );

    let mut names: Vec<String> = String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter_map(|line| line.split_whitespace().next())
        .filter(|name| !name.is_empty())
        .map(str::to_string)
        .collect();
    names.sort();
    names.dedup();
    names
}

/// Our own crates, which are not third-party and have no notice to carry.
const OURS: &[&str] = &["sakatsu-core", "sakatsu-desktop"];

/// Which of `names` the notices do not mention.
///
/// Pure, so the negative test below can hand it a set the working tree does not currently produce.
/// A gate whose failure path is never exercised is a gate nobody has checked.
fn missing_from_notices(names: &[String], text: &str) -> Vec<String> {
    names
        .iter()
        .filter(|name| !OURS.contains(&name.as_str()))
        // Crates rename between the manifest key and the package name only via `package = `,
        // which this does not follow; the underscore/hyphen pair covers the rest.
        .filter(|name| {
            !text.contains(&format!("\n  {name} ")) && !text.contains(&format!("\n{name} "))
        })
        .cloned()
        .collect()
}

#[test]
fn every_shipped_crate_is_named_in_the_notices() {
    let shipped = resolved_graph("sakatsu-desktop", &[]);

    // Teeth: a graph that came back empty or tiny would let this pass having demanded nothing.
    assert!(
        shipped.len() > 200,
        "only {} crates in the release graph, which is too few to be this app — `cargo tree` \
         answered something unexpected",
        shipped.len()
    );

    let missing = missing_from_notices(&shipped, &notices());
    assert!(
        missing.is_empty(),
        "these ship but are not in THIRD-PARTY-NOTICES.txt: {missing:?}\n\
         Regenerate it with: python scripts/collect-licences.py"
    );
}

/// **An optional dependency that a feature turns on is demanded like any other.**
///
/// This is the failure the `optional = true` skip would have hidden. It is exercised rather than
/// argued: `ts-rs` is optional and absent from the release graph, but the moment a feature selects
/// it, it appears in a resolved graph — and it has no notice, so the checker reports it.
///
/// If someone later makes `typescript` a default feature, or another feature comes to depend on it,
/// `every_shipped_crate_is_named_in_the_notices` starts failing for real. That is the point.
#[test]
fn an_enabled_optional_dependency_without_a_notice_is_reported() {
    let enabled = resolved_graph("sakatsu-core", &["typescript"]);
    assert!(
        enabled.iter().any(|name| name == "ts-rs"),
        "ts-rs is optional behind `typescript`; enabling the feature must put it in the graph, or \
         this test is checking nothing"
    );

    let missing = missing_from_notices(&enabled, &notices());
    assert!(
        missing.iter().any(|name| name == "ts-rs"),
        "ts-rs is in an enabled graph and has no notice, so the checker must report it. It did \
         not, which means an optional dependency turned on by a feature could ship unattributed. \
         Reported: {missing:?}"
    );
}

/// And the release build genuinely does not contain it, which is why it has no notice.
///
/// The two halves together are the whole argument: absent from what ships, present the moment it
/// is selected. Neither alone would justify leaving it out of a licence file.
#[test]
fn the_release_graph_excludes_a_feature_gated_dependency() {
    let shipped = resolved_graph("sakatsu-desktop", &[]);
    assert!(
        !shipped.iter().any(|name| name == "ts-rs"),
        "ts-rs reached the release graph. It is a build-time generator and carries no notice — if \
         it now ships, it needs one."
    );
}

#[test]
fn the_notices_carry_licence_texts_and_not_just_names() {
    let text = notices();

    // The two that most of the tree is under. If neither full text is present, the file has been
    // reduced to a list at some point and the obligation is no longer being met.
    assert!(
        text.contains("Apache License")
            && text.contains("TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION"),
        "the Apache-2.0 text is not in the notices"
    );
    assert!(
        text.contains("Permission is hereby granted, free of charge"),
        "the MIT permission notice is not in the notices"
    );
    // A copyright line has to survive too — MIT asks for the notice *and* the copyright.
    assert!(
        text.contains("Copyright"),
        "no copyright lines in the notices, so what is there is not what MIT asks for"
    );
    assert!(
        text.len() > 200_000,
        "the notices are {} bytes, which is too small to be four hundred packages' terms",
        text.len()
    );
}

#[test]
fn the_notices_ship_with_the_app() {
    // Named in `bundle.resources`, or the file exists and is installed nowhere.
    let config = std::fs::read_to_string(root().join("src-tauri").join("tauri.conf.json"))
        .expect("tauri.conf.json is readable");
    assert!(
        config.contains("THIRD-PARTY-NOTICES.txt"),
        "the notices file is not in bundle.resources, so it is not installed with the app"
    );
}

#[test]
fn the_generator_is_still_there() {
    // The file is generated, and a checked-in artefact whose generator has gone is one nobody can
    // safely regenerate — which is how it starts being edited by hand.
    let script = root().join("scripts").join("collect-licences.py");
    assert!(
        Path::new(&script).is_file(),
        "scripts/collect-licences.py is gone, but THIRD-PARTY-NOTICES.txt is generated by it"
    );
}
